insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"WINNER_GTE_6","title":"¿El ganador llegará a 6 o más?","description":"Se corrige con el marcador final.","category":"resultado","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"winner_gte","n":6},"priority":0,"cooldown":2,"tags":["resultado"]},{"code":"WINNER_GTE_7","title":"¿El ganador anotará 7 o más?","description":"Se corrige con el marcador final.","category":"resultado","difficulty":"hard","points":6,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"winner_gte","n":7},"priority":0,"cooldown":2,"tags":["resultado"]},{"code":"WINNER_GTE_8","title":"¿El ganador llegará a 8 o más?","description":"Se corrige con el marcador final.","category":"resultado","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"winner_gte","n":8},"priority":0,"cooldown":2,"tags":["resultado"]},{"code":"WINNER_GTE_9","title":"¿El ganador anotará 9 o más?","description":"Se corrige con el marcador final.","category":"resultado","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"winner_gte","n":9},"priority":0,"cooldown":2,"tags":["resultado"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;